def decode_numbers(encoded_text, offset=9133337):
    nibble_len = len(str(offset)) + 1
    numbers = [encoded_text[i:i+nibble_len] for i in range(0, len(encoded_text), nibble_len)]
    decoded = ''
    for num in numbers:
        try:
            n = int(num)
            n = n - offset
            if n >= 11:
                n = chr(ord('a') + (n - 11))
            else:
                n = str(n)
            decoded += n
        except:
            continue
    return decoded

def decrypt_des(ciphertext, key):
    cipher = DES.new(key, DES.MODE_OFB, IV)
    return cipher.decrypt(ciphertext)

