from Crypto.Cipher import DES
import binascii

# Define weak keys
WEAK_KEYS = [
    '0101010101010101',
    'FEFEFEFEFEFEFEFE',
    'E0E0E0E0F1F1F1F1',
    '1F1F1F1F0E0E0E0E'
]

# IV needs to be 8 bytes
IV = bytes.fromhex('1337133713371337')

def decode_nibble(val, offset=9133337):
    """Convert number back to hex nibble"""
    val = int(val) - offset
    if val >= 11:
        return chr(ord('a') + val - 11)
    return str(val)

def decode_numbers(encoded_text, offset=9133337):
    nibble_len = len(str(offset)) + 1
    hex_string = ""

    # Process each nibble
    for i in range(0, len(encoded_text), nibble_len):
        chunk = encoded_text[i:i+nibble_len]
        try:
            hex_string += decode_nibble(chunk, offset)
        except:
            continue

    # Convert hex pairs to bytes
    try:
        result = bytes.fromhex(hex_string)
        return result
    except Exception as e:
        print(f"Error converting hex to bytes: {e}")
        return None

def decrypt_des(ciphertext, key):
    cipher = DES.new(key, DES.MODE_OFB, IV)
    return cipher.decrypt(ciphertext)

def main():
    print("Starting decryption process...")

    # Read the encrypted flag
    with open('/home/ctfplayer/ctf_files/Challenge/FLAG.enc', 'r') as f:
        encrypted_data = f.read().strip()

    print(f"Read {len(encrypted_data)} bytes of encrypted data")

    # Decode the numbers to binary
    binary_data = decode_numbers(encrypted_data)
    if binary_data:
        print(f"Converted to binary data: {len(binary_data)} bytes")
    else:
        print("Failed to decode numbers to binary")
        return

    # Try all combinations of weak keys
    for key1_hex in WEAK_KEYS:
        key1 = bytes.fromhex(key1_hex)
        for key2_hex in WEAK_KEYS:
            key2 = bytes.fromhex(key2_hex)

            print(f"\nTrying keys: {key1_hex} -> {key2_hex}")

            try:
                # First decrypt with key2, then key1
                intermediate = decrypt_des(binary_data, key2)
                plaintext = decrypt_des(intermediate, key1)

                # Try to decode as ASCII and look for flag
                try:
                    result = plaintext.decode('ascii', errors='ignore')
                    if 'flag{' in result:
                        print(f"\nFound potential flag!")
                        print(f"Key1: {key1_hex}")
                        print(f"Key2: {key2_hex}")
                        print(f"Result: {result}")
                        # Break if we found the flag
                        return
                except Exception as e:
                    continue

            except Exception as e:
                print(f"Error in DES decryption: {e}")
                continue

if __name__ == '__main__':
    main()

